import { describe, it } from "vitest";

describe("Quote premium", () => {
  it.todo("empty item list -> premium 5 G (only the processing fee)");
});

describe("Base premium", () => {
  it.todo("sword -> 100 G");
  it.todo("amulet -> 60 G");
  it.todo("staff -> 80 G");
  it.todo("potion -> 40 G");
  it.todo("1 rune -> 25 G");
  it.todo("1 moonstone -> 25 G");
  it.todo("2 runes -> 50 G");
  it.todo("3 runes -> 60 G (block applies)");
  it.todo("4 runes -> 100 G (no block: block requires exactly 3)");
  it.todo("7 runes -> 175 G");
  it.todo("2 runes + 1 moonstone -> 75 G (no block: alike means the same type)");
  it.todo("3 runes + 3 moonstones -> 120 G (two separate blocks)");
  it.todo("sword + amulet -> 160 G (sum of the item base premiums)");
  it.todo("unknown item type broomstick -> throws ClaimOfficeError (chosen reading of 'rejected')");
});

describe("Premium modifiers", () => {
  it.todo("newcomer, plain sword -> 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("newcomer, cursed sword -> 165 G (100 + 50 curse + 10 first insurance + 5 fee)");
  it.todo("newcomer, sword enchantment 5 -> 145 G (high-enchantment surcharge applies at exactly 5)");
  it.todo("newcomer, cursed sword enchantment 5 -> 195 G (both surcharges apply)");
  it.todo("newcomer, sword enchantment 4 -> 115 G (no high-enchantment surcharge)");
  it.todo("newcomer, cursed sword enchantment 4 -> 165 G (curse surcharge only)");
  it.todo("2 years with MHPCO, plain sword -> 95 G (loyalty discount applies at exactly 2 years)");
  it.todo("1 year with MHPCO, plain sword -> 115 G (no loyalty discount)");
  it.todo("newcomer, plain sword on a follow-up contract -> 100 G (15 % follow-up discount)");
  it.todo("3 years, follow-up contract, cursed sword enchantment 7 -> 160 G (first insurance still applies)");
  it.todo("newcomer, cursed sword + plain amulet -> 231 G (curse applies to the sword's 100 G only: 160 + 50 + 16 + 5)");
  it.todo("newcomer, sword enchantment 5 + plain amulet -> 211 G (high enchantment applies to the sword's 100 G only)");
  it.todo("newcomer, sword + 2 runes + 1 moonstone -> 198 G (197.5 rounded up in the MHPCO's favor)");
});

describe("Insurance sum and cap", () => {
  it.todo("sword -> insurance sum 1000 G, cap 2000 G");
  it.todo("amulet -> insurance sum 600 G");
  it.todo("staff -> insurance sum 800 G");
  it.todo("potion -> insurance sum 400 G");
  it.todo("2 runes -> insurance sum 500 G (250 G per component)");
  it.todo("2 moonstones -> insurance sum 500 G (250 G per component)");
  it.todo("2 swords -> insurance sum 2000 G, cap 4000 G");
  it.todo("sword + amulet -> insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword -> cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("sword + 3 runes -> insurance sum 1750 G (block discount affects premium only)");
});

