input.content:
import { describe, it } from "vitest";

describe("Standard reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G, cap remaining 1600 G");
  it.todo("rune, damage 200 G -> payout 100 G (no enchantment or material, no special clause)");
  it.todo("damage below the deductible (50 G) -> payout 0 G (chosen reading: payout is never negative)");
});

describe("Special reimbursement clauses", () => {
  it.todo("dragon-material sword, enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement)");
  it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
  it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (below the enchantment 8 threshold)");
  it.todo("steel sword, enchantment 9, damage 901 G -> payout 350 G (350.5 rounded down)");
});

describe("Deductible per damage event", () => {
  it.todo("sword damage 500 G + amulet damage 300 G -> payout 600 G (deductible per damaged item)");
  it.todo("two swords insured, two sword damages of 500 G -> payout 800 G (own deductible each)");
  it.todo("two steel swords enchantment 9 insured, two damages of 901 G -> payout 701 G (fractions summed before rounding)");
  it.todo("two swords with enchantment 3 and 9, two sword damages of 800 G -> payout 1000 G (damages matched to swords in policy order; chosen reading)");
});

describe("Cap exhaustion", () => {
  it.todo("sword (cap 2000 G): claim 1500 G -> payout 1400 G, cap remaining 600 G");
  it.todo("sword (cap 2000 G): second claim 1500 G -> payout 600 G, cap remaining 0 G");
});

describe("Claim rejection", () => {
  it.todo("amulet damaged while only a sword is insured -> throws ClaimOfficeError");
  it.todo("damage with unknown item type broomstick -> throws ClaimOfficeError");
  it.todo("damage amount -200 -> throws ClaimOfficeError");
  it.todo("two sword damages while one sword is insured -> throws ClaimOfficeError (whole claim rejected, cap unchanged)");
});

