import { insuranceValueOf } from "./catalog.js";
import type { Item } from "./premium.js";

const CAP_FACTOR = 2;
const DEDUCTIBLE = 100;
const PERCENT = 100;
const FULL_REIMBURSEMENT_PERCENT = 100;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
const HIGH_ENCHANTMENT_CLAUSE_LEVEL = 8;

export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

function reimbursementPercent(item: Item | undefined): number {
  return (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_LEVEL
    ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT
    : FULL_REIMBURSEMENT_PERCENT;
}

function payoutForDamage(damage: Damage, item: Item | undefined): number {
  const reimbursed = (damage.amount * reimbursementPercent(item)) / PERCENT;
  return Math.max(reimbursed - DEDUCTIBLE, 0);
}

export class Policy {
  readonly insuranceSum: number;
  readonly #items: Item[];
  #remainingCap: number;

  constructor(items: Item[]) {
    this.#items = items;
    this.insuranceSum = items.reduce((sum, item) => sum + insuranceValueOf(item.type), 0);
    this.#remainingCap = this.insuranceSum * CAP_FACTOR;
  }

  get remainingCap(): number {
    return this.#remainingCap;
  }

  claim(damages: Damage[]): ClaimResult {
    const payout = damages.reduce(
      (sum, damage) =>
        sum + payoutForDamage(damage, this.#items.find((item) => item.type === damage.itemType)),
      0,
    );
    this.#remainingCap -= payout;
    return { payout, remainingCap: this.#remainingCap };
  }
}

